-- ============================================================
-- 15. 더미 칼럼 정리 + 실제 칼럼 1편 등록
--     실행: node db.js supabase/15_column_quote.sql   (재실행 안전)
--
--     기존 c1/c2/c3 은 picsum 랜덤 이미지(호랑이 사진 등)를 쓰던 더미다.
--     칼럼과 거기 딸린 FAQ를 함께 지우고, 실제 칼럼 한 편을 넣는다.
--     구조는 dfirst.co.kr 칼럼 실측을 따랐다.
--     (질문형 제목 → 인사 도입 → 질문형 소제목 → 표 → FAQ → 회사 소개)
-- ============================================================

-- ---------- 더미 칼럼과 그 FAQ 삭제 ----------
delete from faqs where page in ('c1','c2','c3');
delete from columns_post where id in ('c1','c2','c3');

-- ---------- 새 칼럼 ----------
insert into columns_post (id, cat, date, img, title, excerpt, body, slug, seo_title, seo_desc, published)
values ('c-quote', $json${"ko":"가이드","vi":"Hướng dẫn","en":"Guide"}$json$::jsonb, '2026-08-05', 'assets/img/columns/quote-request.svg',
  $json${"ko":"해외 공급사에 견적을 요청할 때, 무엇을 적어야 할까?","vi":"Gửi yêu cầu báo giá cho nhà cung cấp nước ngoài: cần ghi những gì?","en":"What to put in a quote request to an overseas supplier"}$json$::jsonb, $json${"ko":"견적 요청을 보내고 답이 없다면 대부분 상대가 답을 못 하는 상황입니다. 수량·시기·조건을 어떻게 적어야 하루 만에 회신이 오는지 정리했습니다.","vi":"Gửi yêu cầu báo giá mà không có hồi âm thì phần lớn là do bên kia không thể trả lời. Bài này tóm tắt cách ghi số lượng, thời điểm và điều kiện để nhận phản hồi trong một ngày.","en":"When a quote request goes unanswered, it is usually because the other side cannot answer it. Here is how to state quantity, timing and terms so a reply comes back within a day."}$json$::jsonb, $json${"ko":"<p>안녕하세요, 메이크노브입니다. 견적 요청 메일을 보내고 답이 오지 않는 경우가 많습니다. 상대가 무시해서가 아니라, 받은 내용만으로는 단가를 계산할 수 없어서 답을 못 하는 경우가 대부분입니다.</p>\n\n<h2>견적 회신이 늦어지는 이유는 무엇일까?</h2>\n<p>공급사가 단가를 뽑으려면 최소한 몇 개를, 언제까지 필요한지를 알아야 합니다. 이 두 가지가 없으면 담당자는 \"수량이 어떻게 되나요\"를 다시 물어야 하고, 그 왕복에만 며칠이 갑니다.</p>\n<p>\"가격이 얼마인가요\"만 적힌 메일은 답하기 어려운 질문입니다. 100개와 10,000개의 단가가 다르고, 다음 주 선적과 3개월 뒤 선적의 조건이 다르기 때문입니다.</p>\n\n<h2>견적 요청에 반드시 들어가야 할 항목은?</h2>\n<p>아래 여섯 가지만 채우면 대부분의 공급사가 한 번에 답을 줄 수 있습니다.</p>\n<table>\n<tr><th>희망 수량</th><td>첫 주문 기준 수량. 재주문 계획이 있다면 함께 적으면 조건이 좋아집니다.</td></tr>\n<tr><th>필요 시기</th><td>언제까지 받아야 하는지. 시즌이 걸려 있으면 그것도 적어주세요.</td></tr>\n<tr><th>판매 채널</th><td>약국, 화장품 매장, 마트, 온라인 등. 채널에 따라 포장과 조건이 달라집니다.</td></tr>\n<tr><th>도착지</th><td>도착 항구나 도시. 운임을 포함한 견적을 받으려면 필요합니다.</td></tr>\n<tr><th>필요 서류</th><td>전성분표, 원산지증명서, 시험성적서 등 수입 절차에 필요한 것.</td></tr>\n<tr><th>샘플 여부</th><td>본 발주 전에 샘플을 볼 것인지.</td></tr>\n</table>\n<p>메이크노브의 견적 요청 폼은 이 항목들을 그대로 받게 만들어져 있습니다. 빈칸을 채우면 공급사에게 정리된 형태로 전달됩니다.</p>\n\n<h2>MOQ가 부담될 때는 어떻게 말해야 할까?</h2>\n<p>최소주문수량이 높다고 대화를 접을 필요는 없습니다. 시장 테스트용 소량 주문에 열려 있는 공급사가 생각보다 많습니다. 다만 그냥 \"깎아 달라\"고 하면 답이 어렵습니다.</p>\n<p>대신 이렇게 적으면 협의가 시작됩니다. \"MOQ가 3,000개인 것으로 보입니다. 첫 주문은 500개로 시작해 반응을 보고 분기마다 재주문할 계획입니다. 500개로 가능한 조건이 있을까요?\"</p>\n<p>수량만 낮추는 요청이 아니라 이후 계획까지 보여주는 요청이기 때문입니다. 상세페이지에 <strong>협의 가능</strong> 표시가 붙은 제품은 이런 논의가 가능한 제품입니다.</p>\n\n<h2>수입 공고용 서류는 언제 요청해야 할까?</h2>\n<p>가장 흔한 실수가 발주를 확정한 다음에 서류를 찾는 것입니다. 화장품·식품·의료기기는 수입 전에 제품 공고나 등록 절차를 밟아야 하고, 여기에는 공급사만 줄 수 있는 자료가 들어갑니다.</p>\n<p>그래서 서류는 <strong>견적 단계에서 함께 요청</strong>하는 것이 맞습니다. 공급사가 그 자료를 만들어 본 적이 있는지도 이때 확인됩니다. 없다고 하면 일정을 다시 잡아야 하는데, 그 사실을 발주 후에 아는 것보다 지금 아는 편이 낫습니다.</p>\n\n<h2>메이크노브는</h2>\n<p>전 세계 공급사의 혁신 제품을 한자리에 모아두고, 사업자 인증을 통과한 바이어에게 단가와 최소주문수량을 공개하는 B2B 플랫폼입니다. 문의는 중간상 없이 공급사에 바로 전달되며, 필요하면 화상 미팅도 요청할 수 있습니다.</p>\n<p>가입과 인증은 무료이고 1분 정도 걸립니다.</p>","vi":"<p>Xin chào, MAKENOV đây. Rất nhiều yêu cầu báo giá gửi đi mà không nhận được hồi âm. Phần lớn không phải vì bên kia bỏ qua, mà vì với những gì nhận được họ không thể tính ra đơn giá.</p>\n\n<h2>Vì sao báo giá hay bị chậm?</h2>\n<p>Để tính giá, nhà cung cấp cần biết tối thiểu là bao nhiêu cái và cần khi nào. Thiếu hai điều đó, người phụ trách phải hỏi lại \"số lượng bao nhiêu\", và chỉ riêng vòng hỏi đáp ấy đã mất vài ngày.</p>\n<p>Email chỉ ghi \"giá bao nhiêu\" là câu rất khó trả lời. Giá của 100 cái khác 10.000 cái, và điều kiện giao tuần sau khác giao sau ba tháng.</p>\n\n<h2>Yêu cầu báo giá phải có những mục nào?</h2>\n<p>Chỉ cần điền sáu mục dưới đây, phần lớn nhà cung cấp trả lời được ngay trong một lần.</p>\n<table>\n<tr><th>Số lượng dự kiến</th><td>Số lượng cho đơn đầu. Có kế hoạch đặt lại thì ghi luôn, điều kiện sẽ tốt hơn.</td></tr>\n<tr><th>Thời điểm cần</th><td>Cần nhận trước ngày nào. Nếu gắn với mùa vụ thì ghi rõ.</td></tr>\n<tr><th>Kênh bán</th><td>Nhà thuốc, cửa hàng mỹ phẩm, siêu thị, online. Kênh khác nhau thì đóng gói và điều kiện khác nhau.</td></tr>\n<tr><th>Nơi nhận hàng</th><td>Cảng hoặc thành phố đến. Cần có để nhận báo giá gồm cước.</td></tr>\n<tr><th>Giấy tờ cần</th><td>Bảng thành phần, C/O, phiếu kiểm nghiệm và những gì thủ tục nhập khẩu đòi hỏi.</td></tr>\n<tr><th>Hàng mẫu</th><td>Có cần xem mẫu trước khi đặt chính thức hay không.</td></tr>\n</table>\n<p>Biểu mẫu yêu cầu báo giá của MAKENOV được dựng đúng theo các mục này. Bạn điền vào ô trống, nội dung được chuyển tới nhà cung cấp ở dạng đã sắp xếp.</p>\n\n<h2>Khi MOQ quá cao thì nên nói thế nào?</h2>\n<p>Số lượng tối thiểu cao không có nghĩa là phải dừng câu chuyện. Số nhà cung cấp sẵn sàng nhận đơn thử nghiệm nhiều hơn bạn nghĩ. Nhưng chỉ nói \"giảm giúp tôi\" thì họ khó trả lời.</p>\n<p>Thay vào đó, viết như thế này thì cuộc thương lượng bắt đầu: \"MOQ đang là 3.000 cái. Đơn đầu tôi muốn bắt đầu với 500 cái, xem phản ứng thị trường rồi đặt lại theo quý. Có phương án nào cho mức 500 cái không?\"</p>\n<p>Vì đó không chỉ là xin giảm số lượng mà còn cho thấy kế hoạch phía sau. Sản phẩm có nhãn <strong>có thể thương lượng</strong> trên trang chi tiết là sản phẩm bàn được chuyện này.</p>\n\n<h2>Khi nào nên xin giấy tờ công bố sản phẩm?</h2>\n<p>Sai lầm phổ biến nhất là chốt đơn xong mới đi tìm giấy tờ. Mỹ phẩm, thực phẩm và thiết bị y tế phải công bố hoặc đăng ký trước khi nhập, mà hồ sơ đó có những phần chỉ nhà cung cấp mới cấp được.</p>\n<p>Vì vậy nên <strong>xin ngay ở bước báo giá</strong>. Đây cũng là lúc biết được nhà cung cấp đã từng làm hồ sơ này chưa. Nếu chưa thì phải tính lại lịch, và biết điều đó bây giờ vẫn hơn là biết sau khi đã đặt hàng.</p>\n\n<h2>Về MAKENOV</h2>\n<p>MAKENOV là nền tảng B2B tập hợp sản phẩm đổi mới của các nhà cung cấp toàn cầu, và mở đơn giá cùng số lượng tối thiểu cho nhà mua đã xác thực doanh nghiệp. Yêu cầu đi thẳng tới nhà cung cấp, không qua trung gian, và bạn có thể đặt lịch gặp qua video khi cần.</p>\n<p>Đăng ký và xác thực miễn phí, mất khoảng một phút.</p>","en":"<p>Hello, this is MAKENOV. A lot of quote requests go out and never come back. Usually it is not that the other side ignored you: with what they received, they simply cannot work out a price.</p>\n\n<h2>Why do quotes come back slowly?</h2>\n<p>To price anything, a supplier needs to know how many and by when. Without those two, the person handling it has to write back asking \"what quantity?\", and that round trip alone costs days.</p>\n<p>An email that only asks \"how much is it?\" is a hard question to answer. A hundred units and ten thousand units are different prices, and shipping next week is a different arrangement from shipping in three months.</p>\n\n<h2>What must a quote request contain?</h2>\n<p>Fill in these six and most suppliers can answer in one pass.</p>\n<table>\n<tr><th>Target quantity</th><td>For the first order. If you plan to reorder, say so and the terms usually improve.</td></tr>\n<tr><th>When you need it</th><td>The date you must have it by, and the season if one applies.</td></tr>\n<tr><th>Sales channel</th><td>Pharmacy, cosmetics stores, supermarket, online. Packaging and terms follow the channel.</td></tr>\n<tr><th>Destination</th><td>Arrival port or city, needed for any quote that includes freight.</td></tr>\n<tr><th>Documents</th><td>Ingredient list, certificate of origin, test reports and whatever your import process requires.</td></tr>\n<tr><th>Samples</th><td>Whether you want to see samples before the main order.</td></tr>\n</table>\n<p>The MAKENOV quote form is built around exactly these fields. Fill the blanks and the supplier receives it already organised.</p>\n\n<h2>What if the MOQ is too high?</h2>\n<p>A high minimum is not a reason to end the conversation. More suppliers are open to trial orders than you would expect. But \"can you lower it\" on its own is hard to answer.</p>\n<p>This gets a negotiation started instead: \"Your MOQ appears to be 3,000 units. We would like to start at 500, see how the market responds, and reorder quarterly. Is there an arrangement that works at 500?\"</p>\n<p>It is not only a request to cut the quantity; it shows what comes after. Products tagged <strong>negotiable</strong> on the detail page are the ones where this discussion is possible.</p>\n\n<h2>When should you ask for import documents?</h2>\n<p>The most common mistake is going looking for paperwork after the order is placed. Cosmetics, food and medical devices need product notification or registration before import, and parts of that dossier only the supplier can provide.</p>\n<p>So ask for them <strong>at the quote stage</strong>. That is also when you find out whether the supplier has produced such a dossier before. If they have not, the schedule needs rethinking, and it is better to learn that now than after you have ordered.</p>\n\n<h2>About MAKENOV</h2>\n<p>MAKENOV is a B2B platform that gathers innovative products from suppliers worldwide and opens unit prices and minimum order quantities to buyers who pass business verification. Requests go straight to the supplier with no middleman, and you can request a video meeting when you need one.</p>\n<p>Signing up and verifying is free and takes about a minute.</p>"}$json$::jsonb,
  'quote-request-checklist', '해외 공급사 견적 요청서 작성법 — 수량·MOQ·납기 체크리스트', '견적 회신이 늦는 이유와 요청서에 반드시 들어가야 할 6가지 항목, MOQ 협의 요령, 수입 공고용 서류 요청 시점까지 정리했습니다.', true)
on conflict (id) do update set
  cat=excluded.cat, date=excluded.date, img=excluded.img,
  title=excluded.title, excerpt=excluded.excerpt, body=excluded.body,
  slug=excluded.slug, seo_title=excluded.seo_title, seo_desc=excluded.seo_desc,
  published=true;

-- ---------- 이 칼럼의 FAQ ----------
insert into faqs (id, page, sort, q, a, published)
values ('cqf1', 'c-quote', 1, $json${"ko":"견적 요청과 간단 문의는 어떻게 다른가요?","vi":"Yêu cầu báo giá và hỏi nhanh khác nhau thế nào?","en":"How is a quote request different from a quick question?"}$json$::jsonb, $json${"ko":"견적 요청은 수량과 시기를 받아 단가를 뽑는 절차이고, 간단 문의는 수량과 무관한 질문을 짧게 주고받는 창구입니다. 아직 수량을 못 정했다면 간단 문의가 빠릅니다.","vi":"Yêu cầu báo giá là quy trình lấy số lượng và thời điểm để tính đơn giá; hỏi nhanh là kênh trao đổi ngắn cho những câu không liên quan số lượng. Chưa chốt số lượng thì hỏi nhanh sẽ nhanh hơn.","en":"A quote request takes your quantity and timing to produce a price. A quick question is a short exchange for anything unrelated to volume. If the quantity is not settled, the quick route is faster."}$json$::jsonb, true)
on conflict (id) do update set page=excluded.page, sort=excluded.sort,
  q=excluded.q, a=excluded.a, published=true;

insert into faqs (id, page, sort, q, a, published)
values ('cqf2', 'c-quote', 2, $json${"ko":"단가를 보려면 꼭 인증해야 하나요?","vi":"Có bắt buộc xác thực mới xem được giá không?","en":"Do I have to verify to see prices?"}$json$::jsonb, $json${"ko":"네. 단가와 최소주문수량은 사업자 인증을 통과한 계정에만 전송됩니다. 공급사가 실제 수출 단가를 공개하는 조건이기 때문입니다. 인증은 무료이고 1분 정도 걸립니다.","vi":"Có. Đơn giá và số lượng tối thiểu chỉ được gửi tới tài khoản đã xác thực doanh nghiệp, vì đó là điều kiện để nhà cung cấp công khai giá xuất khẩu thật. Xác thực miễn phí, mất khoảng một phút.","en":"Yes. Unit price and minimum order quantity are sent only to verified accounts, because that is the condition on which suppliers publish real export pricing. Verification is free and takes about a minute."}$json$::jsonb, true)
on conflict (id) do update set page=excluded.page, sort=excluded.sort,
  q=excluded.q, a=excluded.a, published=true;

insert into faqs (id, page, sort, q, a, published)
values ('cqf3', 'c-quote', 3, $json${"ko":"여러 제품을 한 번에 물어볼 수 있나요?","vi":"Hỏi nhiều sản phẩm cùng lúc được không?","en":"Can I ask about several products at once?"}$json$::jsonb, $json${"ko":"관심제품에 담아두고 일괄 견적을 요청하면 각 공급사에 따로 전달됩니다. 조건을 나란히 놓고 비교하실 수 있습니다.","vi":"Lưu vào danh sách quan tâm rồi gửi yêu cầu hàng loạt, mỗi yêu cầu sẽ tới đúng nhà cung cấp của nó. Bạn đặt các điều kiện cạnh nhau mà so.","en":"Save them to your wishlist and send a bulk request; each one reaches its own supplier, and you can line the terms up side by side."}$json$::jsonb, true)
on conflict (id) do update set page=excluded.page, sort=excluded.sort,
  q=excluded.q, a=excluded.a, published=true;

insert into faqs (id, page, sort, q, a, published)
values ('cqf4', 'c-quote', 4, $json${"ko":"답변은 보통 얼마나 걸리나요?","vi":"Thường bao lâu thì có trả lời?","en":"How long does a reply take?"}$json$::jsonb, $json${"ko":"영업일 1~3일입니다. 사흘이 지나도 소식이 없으면 고객센터로 제품명과 함께 알려주세요. 저희가 공급사에 직접 확인합니다.","vi":"Khoảng 1–3 ngày làm việc. Quá ba ngày chưa có tin, hãy báo bộ phận hỗ trợ kèm tên sản phẩm, chúng tôi sẽ xác nhận trực tiếp với nhà cung cấp.","en":"One to three business days. If three days pass with nothing, tell support with the product name and we will check with the supplier directly."}$json$::jsonb, true)
on conflict (id) do update set page=excluded.page, sort=excluded.sort,
  q=excluded.q, a=excluded.a, published=true;

insert into faqs (id, page, sort, q, a, published)
values ('cqf5', 'c-quote', 5, $json${"ko":"견적서를 받은 뒤에는 무엇을 확인해야 하나요?","vi":"Sau khi nhận báo giá thì cần kiểm tra gì?","en":"What should I check once the quote arrives?"}$json$::jsonb, $json${"ko":"단가의 기준 조건(FOB인지 CIF인지), 유효 기간, 결제 조건, 그리고 납기가 발주 확정일 기준인지 확인하세요. 이 네 가지가 빠진 견적은 나중에 말이 달라질 수 있습니다.","vi":"Kiểm tra điều kiện của giá (FOB hay CIF), thời hạn hiệu lực, điều kiện thanh toán, và thời gian giao tính từ ngày chốt đơn hay không. Thiếu bốn mục này thì về sau dễ phát sinh tranh cãi.","en":"Check the pricing basis (FOB or CIF), how long the quote is valid, payment terms, and whether the lead time counts from order confirmation. A quote missing these four tends to shift later."}$json$::jsonb, true)
